import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define OC_TILE 2
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int groups,
    int in_channels_per_group, int out_channels_per_group,
    int num_oc_tiles)
{
    // Each block now handles OC_TILE output channels for a fixed (batch, group, tile)
    // so that input values fetched from global memory (which are identical across
    // output channels within the same group) are reused OC_TILE times instead of
    // being reloaded once per output channel. Weight for all OC_TILE channels is
    // staged once in shared memory, as before, and (od,oh)-dependent kd/kh valid
    // index lookups are cached in shared memory as before.
    int tile_block = blockIdx.y;
    int g = tile_block / num_oc_tiles;
    int tile_idx = tile_block % num_oc_tiles;
    int oc_start_in_group = tile_idx * OC_TILE;
    int b = blockIdx.z;
    extern __shared__ float s_mem[];
    int kernel_vol = kD * kH * kW;
    int weight_size_per_oc = in_channels_per_group * kernel_vol;
    int weight_size = weight_size_per_oc * OC_TILE;
    float* s_weight = s_mem;
    int* s_id = (int*)(s_weight + weight_size);
    int* s_ih = s_id + kD;
    for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
        int t = i / weight_size_per_oc;
        int rem = i % weight_size_per_oc;
        int ic_in_group = rem / kernel_vol;
        int k = rem % kernel_vol;
        int oc_in_group = oc_start_in_group + t;
        float val = 0.0f;
        if (oc_in_group < out_channels_per_group) {
            int ic = g * in_channels_per_group + ic_in_group;
            int weight_idx = ((ic * out_channels_per_group + oc_in_group) * kernel_vol) + k;
            val = weight[weight_idx];
        }
        s_weight[i] = val;
    }
    __syncthreads();
    long combo_total = (long)D_out * H_out;
    long combo_stride = gridDim.x;
    for (long combo = blockIdx.x; combo < combo_total; combo += combo_stride) {
        int oh = (int)(combo % H_out);
        int od = (int)(combo / H_out);
        for (int kd = threadIdx.x; kd < kD; kd += blockDim.x) {
            int id_nom = od + pad_d - kd;
            int id = -1;
            if (id_nom % stride_d == 0) {
                int cand = id_nom / stride_d;
                if (cand >= 0 && cand < D_in) id = cand;
            }
            s_id[kd] = id;
        }
        for (int kh = threadIdx.x; kh < kH; kh += blockDim.x) {
            int ih_nom = oh + pad_h - kh;
            int ih = -1;
            if (ih_nom % stride_h == 0) {
                int cand = ih_nom / stride_h;
                if (cand >= 0 && cand < H_in) ih = cand;
            }
            s_ih[kh] = ih;
        }
        __syncthreads();
        const int ELEMS = 4;
        for (int ow_base = threadIdx.x * ELEMS; ow_base < W_out; ow_base += blockDim.x * ELEMS) {
            float sum[OC_TILE][ELEMS];
            #pragma unroll
            for (int t = 0; t < OC_TILE; t++) {
                #pragma unroll
                for (int e = 0; e < ELEMS; e++) sum[t][e] = 0.0f;
            }
            int ow_vals[ELEMS];
            #pragma unroll
            for (int e = 0; e < ELEMS; e++) ow_vals[e] = ow_base + e;
            for (int ic_in_group = 0; ic_in_group < in_channels_per_group; ic_in_group++) {
                int ic = g * in_channels_per_group + ic_in_group;
                int w_base = ic_in_group * kernel_vol;
                for (int kd = 0; kd < kD; kd++) {
                    int id = s_id[kd];
                    if (id < 0) continue;
                    for (int kh = 0; kh < kH; kh++) {
                        int ih = s_ih[kh];
                        if (ih < 0) continue;
                        int w_base2 = w_base + (kd * kH + kh) * kW;
                        int in_base = (((b * in_channels + ic) * D_in + id) * H_in + ih) * W_in;
                        for (int kw = 0; kw < kW; kw++) {
                            #pragma unroll
                            for (int e = 0; e < ELEMS; e++) {
                                int ow = ow_vals[e];
                                if (ow >= W_out) continue;
                                int iw_nom = ow + pad_w - kw;
                                if (iw_nom % stride_w != 0) continue;
                                int iw = iw_nom / stride_w;
                                if (iw < 0 || iw >= W_in) continue;
                                float in_val = input[in_base + iw];
                                #pragma unroll
                                for (int t = 0; t < OC_TILE; t++) {
                                    float wv = s_weight[t * weight_size_per_oc + w_base2 + kw];
                                    sum[t][e] += in_val * wv;
                                }
                            }
                        }
                    }
                }
            }
            #pragma unroll
            for (int t = 0; t < OC_TILE; t++) {
                int oc_in_group = oc_start_in_group + t;
                if (oc_in_group >= out_channels_per_group) continue;
                int oc = g * out_channels_per_group + oc_in_group;
                #pragma unroll
                for (int e = 0; e < ELEMS; e++) {
                    int ow = ow_vals[e];
                    if (ow >= W_out) continue;
                    float total = sum[t][e];
                    if (bias != nullptr) {
                        total += bias[oc];
                    }
                    int output_idx = (((b * out_channels + oc) * D_out + od) * H_out + oh) * W_out + ow;
                    output[output_idx] = total;
                }
            }
        }
        __syncthreads();
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int batch = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int in_channels_per_group = in_channels / groups;
    int D_out = (D_in - 1) * stride_d - 2 * pad_d + kD + out_pad_d;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + kH + out_pad_h;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + kW + out_pad_w;
    auto output = torch::zeros({batch, out_channels, D_out, H_out, W_out}, input.options());
    long combo_total = (long)D_out * H_out;
    const int ELEMS_HOST = 4;
    int needed_threads = (W_out + ELEMS_HOST - 1) / ELEMS_HOST;
    int threads = ((needed_threads + 31) / 32) * 32;
    if (threads < 32) threads = 32;
    if (threads > 256) threads = 256;
    long blocksX_l = combo_total;
    if (blocksX_l < 1) blocksX_l = 1;
    if (blocksX_l > 65535) blocksX_l = 65535;
    int blocksX = (int)blocksX_l;
    int num_oc_tiles = (out_channels_per_group + OC_TILE - 1) / OC_TILE;
    int gridY = groups * num_oc_tiles;
    dim3 grid(blocksX, gridY, batch);
    dim3 block(threads);
    int kernel_vol = kD * kH * kW;
    size_t shared_mem_size = (size_t)in_channels_per_group * kernel_vol * OC_TILE * sizeof(float) + (size_t)(kD + kH) * sizeof(int);
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch, in_channels, out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        groups,
        in_channels_per_group, out_channels_per_group,
        num_oc_tiles
    );
    return output;
}
"""

conv_transpose3d_header = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int out_pad_d, int out_pad_h, int out_pad_w,
    int groups);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_header,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
