class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        # Use nn.ConvTranspose3d to initialize weight/bias exactly like PyTorch does
        ref = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                  stride=stride, padding=padding,
                                  output_padding=output_padding, groups=groups, bias=bias)

        self.weight = nn.Parameter(ref.weight.data.clone())
        if bias:
            self.bias = nn.Parameter(ref.bias.data.clone())
        else:
            self.register_parameter('bias', None)

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.conv_transpose3d_cuda = conv_transpose3d_module.conv_transpose3d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias_tensor = self.bias.cuda().contiguous() if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)

        out = self.conv_transpose3d_cuda(
            x, weight, bias_tensor,
            self.stride[0], self.stride[1], self.stride[2],
            self.padding[0], self.padding[1], self.padding[2],
            self.output_padding[0], self.output_padding[1], self.output_padding[2],
            self.groups
        )
        return out


